/** Primary platform admin — new builds, Platform Hub & beta features. */
export function getAdminEmail(): string {
  return (import.meta.env.VITE_ADMIN_EMAIL as string | undefined)?.trim().toLowerCase() ?? "";
}

/** Legacy analyst — classic Threat Intel only (no new modules). */
const LEGACY_ANALYSTS = [
  "microntest4@gmail.com",
];

export function isPlatformAdmin(email: string | null | undefined): boolean {
  if (!email) return false;
  const admin = getAdminEmail();
  if (!admin) return false;
  return email.trim().toLowerCase() === admin;
}

export function isLegacyAnalyst(email: string | null | undefined): boolean {
  if (!email) return false;
  return LEGACY_ANALYSTS.includes(email.trim().toLowerCase());
}

/** Classic Threat Intel dashboard + sidebar (Index, feeds, IOCs, etc.). */
export function hasThreatIntelAccess(email: string | null | undefined): boolean {
  return isPlatformAdmin(email) || isLegacyAnalyst(email);
}

/** Platform Hub, SOC module blocks, experimental tools — admin only. */
export function hasPlatformHubAccess(email: string | null | undefined): boolean {
  return isPlatformAdmin(email);
}

/** Gate all new features you build going forward. */
export function canAccessNewFeatures(email: string | null | undefined): boolean {
  return isPlatformAdmin(email);
}

/** Routes that legacy analysts must not open (redirect to /). */
export const ADMIN_ONLY_PATHS = [
  "/hub",
  "/ai-assessment",
  "/cloud-cspm",
  "/customer-onboarding",
  "/ai-research-lab",
  "/company",
] as const;
